'use client'

import { Check } from 'lucide-react'
import { cn } from '@/lib/utils'

interface StepIndicatorProps {
  currentStep: number
  steps: string[]
}

export function StepIndicator({ currentStep, steps }: StepIndicatorProps) {
  const total = steps.length

  return (
    <nav aria-label="Onboarding progress">
      {/* Desktop: full circles + connectors + labels */}
      <div className="hidden sm:flex items-center w-full" role="list">
        {steps.map((label, i) => {
          const stepNum = i + 1
          const isCompleted = stepNum < currentStep
          const isActive = stepNum === currentStep
          // Connector is "completed" if its left circle is completed
          const connectorDone = i < currentStep - 1

          return (
            <div key={label} className="flex flex-1 items-center">
              {/* Step circle + label column */}
              <div className="flex flex-col items-center" role="listitem">
                <div
                  aria-current={isActive ? 'step' : undefined}
                  aria-label={
                    isCompleted
                      ? `${label} — completed`
                      : isActive
                        ? `${label} — current`
                        : `${label} — upcoming`
                  }
                  className={cn(
                    'size-8 rounded-full flex items-center justify-center transition-all duration-200 ease-out',
                    isActive &&
                      'bg-rust text-bone shadow-[0_0_0_4px_color-mix(in_oklch,var(--color-rust)_12%,transparent)]',
                    isCompleted && 'bg-onyx text-bone',
                    !isActive && !isCompleted && 'bg-bone border border-border text-stone',
                  )}
                >
                  {isCompleted ? (
                    <Check className="size-4 text-bone" strokeWidth={2.5} aria-hidden="true" />
                  ) : (
                    <span className="font-sans text-[13px] font-semibold leading-none tabular-nums">
                      {stepNum}
                    </span>
                  )}
                </div>
                <span
                  className={cn(
                    'hidden sm:block mt-2 text-[10px] font-semibold uppercase tracking-[0.08em] text-center whitespace-nowrap',
                    isActive ? 'text-onyx' : 'text-stone',
                  )}
                >
                  {label}
                </span>
              </div>

              {/* Connector line (not after last step) */}
              {i < total - 1 && (
                <div
                  aria-hidden="true"
                  className={cn(
                    'flex-1 h-px mx-2 mb-5 transition-colors duration-200 ease-out',
                    connectorDone ? 'bg-onyx' : 'bg-border',
                  )}
                />
              )}
            </div>
          )
        })}
      </div>

      {/* Mobile: dots + "Step N of N" counter */}
      <div className="flex sm:hidden items-center justify-between" role="list">
        <div className="flex items-center gap-2">
          {steps.map((label, i) => {
            const stepNum = i + 1
            const isCompleted = stepNum < currentStep
            const isActive = stepNum === currentStep

            return (
              <div
                key={label}
                role="listitem"
                aria-label={
                  isCompleted
                    ? `${label} — completed`
                    : isActive
                      ? `${label} — current`
                      : `${label} — upcoming`
                }
                className={cn(
                  'size-1.5 rounded-full transition-all duration-200 ease-out',
                  isActive && 'bg-rust',
                  isCompleted && 'bg-onyx',
                  !isActive && !isCompleted && 'bg-bone border border-stone',
                )}
              />
            )
          })}
        </div>
        <span
          aria-live="polite"
          className="font-sans text-[12px] font-semibold text-stone"
        >
          Step {currentStep} of {total}
        </span>
      </div>
    </nav>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { slugify } from '@/lib/utils'

interface SlugPreviewProps {
  studioName: string
}

export function SlugPreview({ studioName }: SlugPreviewProps) {
  const [debouncedSlug, setDebouncedSlug] = useState(() => slugify(studioName))

  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedSlug(slugify(studioName))
    }, 200)
    return () => clearTimeout(timer)
  }, [studioName])

  const isEmpty = !studioName.trim()

  return (
    <p
      className="mt-2 flex items-center overflow-hidden"
      aria-live="polite"
      aria-label={
        isEmpty
          ? 'Booking URL preview: book.inkos.app/your-studio-name'
          : `Your booking URL: book.inkos.app/${debouncedSlug}`
      }
    >
      <span className="font-mono text-xs text-stone leading-none whitespace-nowrap shrink-0">
        book.inkos.app/
      </span>
      {isEmpty ? (
        <span className="font-serif italic text-xs text-stone leading-none overflow-hidden text-ellipsis max-w-[calc(100%-9rem)]">
          your-studio-name
        </span>
      ) : (
        <span className="font-mono text-xs font-medium text-onyx leading-none overflow-hidden text-ellipsis max-w-[calc(100%-9rem)]">
          {debouncedSlug}
        </span>
      )}
    </p>
  )
}

'use client'

import { useEffect, useRef, useState } from 'react'
import { ChevronDown, Check } from 'lucide-react'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover'
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from '@/components/ui/command'
import { getAllTimezones, detectBrowserTimezone, formatTimezoneLabel } from '@/lib/onboarding/timezone'
import { cn } from '@/lib/utils'

interface TimezoneComboboxProps {
  value: string
  onValueChange: (tz: string) => void
  id?: string
}

export function TimezoneCombobox({ value, onValueChange, id }: TimezoneComboboxProps) {
  const [open, setOpen] = useState(false)
  const groups = useRef<Record<string, string[]> | null>(null)

  // Lazily compute timezone groups once
  if (!groups.current) {
    groups.current = getAllTimezones()
  }

  const continents = Object.keys(groups.current).sort()

  // Auto-detect on mount if no value set
  useEffect(() => {
    if (!value) {
      const detected = detectBrowserTimezone()
      if (detected) {
        onValueChange(detected)
      }
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  function handleSelect(tz: string) {
    onValueChange(tz)
    setOpen(false)
  }

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <button
          id={id}
          type="button"
          role="combobox"
          aria-haspopup="listbox"
          aria-expanded={open}
          aria-label="Select timezone"
          className={cn(
            'flex h-9 w-full items-center justify-between rounded-md border border-input bg-bone px-3 py-1',
            'font-sans text-[14px] font-normal text-onyx',
            'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-0',
            'disabled:cursor-not-allowed disabled:opacity-50',
            'cursor-pointer',
            !value && 'text-stone',
          )}
        >
          <span className="truncate">
            {value ? formatTimezoneLabel(value) : 'Select timezone…'}
          </span>
          <ChevronDown className="size-4 text-stone shrink-0 ml-2" aria-hidden="true" />
        </button>
      </PopoverTrigger>
      <PopoverContent
        className="w-[--radix-popover-trigger-width] p-0 bg-bone border border-stone rounded-xl shadow-[var(--shadow-lift)] max-h-64 overflow-hidden"
        align="start"
        role="listbox"
      >
        <Command>
          <CommandInput
            placeholder="Search timezones…"
            className="font-sans text-[14px] text-onyx placeholder:text-stone"
            aria-label="Search timezones"
          />
          <CommandList className="max-h-48 overflow-y-auto">
            <CommandEmpty className="font-serif italic text-[14px] text-stone py-6 text-center">
              Couldn&apos;t find that timezone. Try &ldquo;New York&rdquo; or &ldquo;London&rdquo;.
            </CommandEmpty>
            {continents.map((continent) => (
              <CommandGroup
                key={continent}
                heading={continent}
                className="[&_[cmdk-group-heading]]:font-sans [&_[cmdk-group-heading]]:text-[10px] [&_[cmdk-group-heading]]:font-semibold [&_[cmdk-group-heading]]:uppercase [&_[cmdk-group-heading]]:tracking-[0.08em] [&_[cmdk-group-heading]]:text-stone [&_[cmdk-group-heading]]:px-3 [&_[cmdk-group-heading]]:py-1.5"
              >
                {(groups.current![continent] ?? []).map((tz) => (
                  <CommandItem
                    key={tz}
                    value={tz}
                    onSelect={() => handleSelect(tz)}
                    className="font-sans text-[14px] font-normal text-onyx cursor-pointer px-3 py-2 hover:bg-accent rounded-lg mx-1 flex items-center justify-between aria-selected:bg-accent"
                    role="option"
                    aria-selected={value === tz}
                  >
                    <span>{formatTimezoneLabel(tz)}</span>
                    {value === tz && (
                      <Check className="size-4 text-onyx" aria-hidden="true" />
                    )}
                  </CommandItem>
                ))}
              </CommandGroup>
            ))}
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  )
}

'use client'

import { useEffect, useRef, useState } from 'react'
import { cn } from '@/lib/utils'
import { SERVICE_TEMPLATES, type ServiceTemplate } from '@/lib/onboarding/service-templates'

interface ServiceTemplatePickerProps {
  value: string | null
  onChange: (templateId: string, template: ServiceTemplate) => void
}

function formatDuration(min: number): string {
  if (min < 60) return `${min} min`
  const hrs = min / 60
  return hrs === Math.floor(hrs) ? `${hrs} hrs` : `${hrs} hrs`
}

function formatPrice(cents: number): string {
  if (cents === 0) return 'Free'
  return `$${(cents / 100).toLocaleString('en-US', { minimumFractionDigits: 0 })}`
}

export function ServiceTemplatePicker({ value, onChange }: ServiceTemplatePickerProps) {
  // focusedIndex for roving tabIndex keyboard nav
  const initialFocus = value
    ? SERVICE_TEMPLATES.findIndex((t) => t.id === value)
    : 0
  const [focusedIndex, setFocusedIndex] = useState(initialFocus < 0 ? 0 : initialFocus)
  const cardRefs = useRef<(HTMLDivElement | null)[]>([])

  useEffect(() => {
    // When focusedIndex changes, programmatically focus that card
    cardRefs.current[focusedIndex]?.focus()
  }, [focusedIndex])

  function handleKeyDown(e: React.KeyboardEvent<HTMLDivElement>, index: number) {
    const total = SERVICE_TEMPLATES.length
    if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
      e.preventDefault()
      setFocusedIndex((focusedIndex + 1) % total)
    } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
      e.preventDefault()
      setFocusedIndex((focusedIndex - 1 + total) % total)
    } else if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault()
      const tpl = SERVICE_TEMPLATES[index]
      if (tpl) {
        onChange(tpl.id, tpl)
      }
    }
    // Tab: let browser handle naturally — exits the grid
  }

  return (
    <div
      role="listbox"
      aria-label="Service templates"
      className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3"
    >
      {SERVICE_TEMPLATES.map((tpl, index) => {
        const isSelected = value === tpl.id
        const isRecommended = 'recommended' in tpl && tpl.recommended === true
        const isFree = tpl.basePrice === 0
        const isCustom = tpl.id === 'custom'

        return (
          <div
            key={tpl.id}
            ref={(el) => { cardRefs.current[index] = el }}
            role="option"
            aria-selected={isSelected}
            aria-label={isRecommended ? `${tpl.name}, most studios pick this` : tpl.name}
            tabIndex={focusedIndex === index ? 0 : -1}
            onClick={() => {
              setFocusedIndex(index)
              onChange(tpl.id, tpl)
            }}
            onKeyDown={(e) => handleKeyDown(e, index)}
            className={cn(
              'group relative cursor-pointer rounded-xl border bg-bone p-4 flex flex-col gap-1',
              'transition-all duration-150 ease-out',
              'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2',
              isSelected
                ? 'border-onyx shadow-[var(--shadow-card-hover)]'
                : 'border-border hover:border-stone hover:shadow-[var(--shadow-card)]',
            )}
          >
            {/* Recommended badge — one Rust accent per viewport */}
            {isRecommended && (
              <div className="absolute top-3 right-3 flex items-center gap-1" aria-hidden="true">
                <span className="size-1.5 rounded-full bg-rust" />
                <span className="font-sans text-[10px] font-semibold text-stone uppercase tracking-[0.06em]">
                  Most studios pick this
                </span>
              </div>
            )}

            <span className="font-sans text-[15px] font-bold text-onyx leading-snug">
              {tpl.name}
            </span>

            <span className="font-mono text-[13px] font-medium text-stone tabular-nums">
              {isCustom
                ? '— · —'
                : `${formatDuration(tpl.durationMin)} · ${isFree ? 'Free' : formatPrice(tpl.basePrice * 100)}`}
            </span>

            <span className="font-sans text-[12px] font-normal text-stone">
              {isCustom
                ? 'You fill in the details'
                : tpl.depositPct === 0
                  ? 'No deposit'
                  : `${tpl.depositPct}% deposit required`}
            </span>
          </div>
        )
      })}
    </div>
  )
}

'use client'

import { useEffect, useRef, useState } from 'react'
import { Square, CheckSquare, ArrowRight } from 'lucide-react'
import { toast } from 'sonner'
import QRCode from 'qrcode'
import { Button } from '@/components/ui/button'
import { BOOKING_DOMAIN } from '@/lib/onboarding/constants'
import { cn } from '@/lib/utils'

interface ChecklistState {
  logoAdded: boolean
  teamInvited: boolean
  hoursSet: boolean
  payoutConnected: boolean
}

interface BookingLinkCardProps {
  slug: string
  studioName: string
  checklist?: ChecklistState
}

const CHECKLIST_ITEMS = [
  {
    key: 'logoAdded' as const,
    label: 'Add your logo',
    href: '/settings/studio',
  },
  {
    key: 'teamInvited' as const,
    label: 'Invite your team',
    href: '/settings/team/members',
  },
  {
    key: 'hoursSet' as const,
    label: 'Set your hours',
    href: '/settings/studio',
  },
  {
    key: 'payoutConnected' as const,
    label: 'Connect your payout account',
    href: '/settings/billing',
  },
]

export function BookingLinkCard({
  slug,
  studioName,
  checklist = { logoAdded: false, teamInvited: false, hoursSet: false, payoutConnected: false },
}: BookingLinkCardProps) {
  const bookingUrl = `https://${BOOKING_DOMAIN}/${slug}`
  const displayUrl = `${BOOKING_DOMAIN}/${slug}`

  const [qrSvg, setQrSvg] = useState<string>('')
  const [copyLinkLabel, setCopyLinkLabel] = useState<'Copy link' | 'Copied'>('Copy link')
  const [copyIgLabel, setCopyIgLabel] = useState<'Copy for Instagram bio' | 'Copied'>('Copy for Instagram bio')

  // Generate QR code as SVG
  useEffect(() => {
    QRCode.toString(bookingUrl, {
      type: 'svg',
      color: { dark: '#0F0F0F', light: '#F7F7F5' },
      margin: 0,
      width: 96,
      errorCorrectionLevel: 'M',
    })
      .then((svg) => setQrSvg(svg))
      .catch(() => {
        // QR generation failure is non-fatal — card still shows URL
      })
  }, [bookingUrl])

  const copyLinkTimeout = useRef<ReturnType<typeof setTimeout> | null>(null)
  const copyIgTimeout = useRef<ReturnType<typeof setTimeout> | null>(null)

  function handleCopyLink() {
    navigator.clipboard.writeText(bookingUrl)
      .then(() => {
        setCopyLinkLabel('Copied')
        toast.success('Link copied to clipboard')
        if (copyLinkTimeout.current) clearTimeout(copyLinkTimeout.current)
        copyLinkTimeout.current = setTimeout(() => setCopyLinkLabel('Copy link'), 1500)
      })
      .catch(() => toast.error('Could not copy to clipboard'))
  }

  function handleCopyIg() {
    const payload = `📍 Book now\n${BOOKING_DOMAIN}/${slug}`
    navigator.clipboard.writeText(payload)
      .then(() => {
        setCopyIgLabel('Copied')
        toast.success('Instagram bio text copied')
        if (copyIgTimeout.current) clearTimeout(copyIgTimeout.current)
        copyIgTimeout.current = setTimeout(() => setCopyIgLabel('Copy for Instagram bio'), 1500)
      })
      .catch(() => toast.error('Could not copy to clipboard'))
  }

  return (
    <div
      className="rounded-xl border border-onyx bg-bone shadow-[var(--shadow-card)] p-5"
      aria-label="Your booking page details"
    >
      {/* URL + QR row */}
      <div className="flex flex-col sm:flex-row items-start justify-between gap-4">
        <div className="flex-1 min-w-0">
          <p className="font-sans text-[10px] font-semibold uppercase tracking-[0.08em] text-stone mb-2">
            Your booking page
          </p>
          <p
            className="font-mono text-[16px] font-medium text-onyx leading-snug tabular-nums break-all"
            role="text"
            aria-label={`Booking URL: ${displayUrl}`}
          >
            {displayUrl}
          </p>
        </div>

        {qrSvg && (
          <div
            className="w-24 h-24 shrink-0 [&_svg]:w-full [&_svg]:h-full"
            role="img"
            aria-label={`QR code for ${bookingUrl}`}
            dangerouslySetInnerHTML={{ __html: qrSvg }}
          />
        )}
      </div>

      {/* Action buttons */}
      <div className="flex flex-col sm:flex-row gap-2 mt-5">
        <Button
          type="button"
          variant="default"
          className="w-full sm:w-auto"
          onClick={handleCopyLink}
          aria-label={copyLinkLabel === 'Copied' ? 'Booking link copied' : 'Copy booking link'}
        >
          {copyLinkLabel}
        </Button>

        <Button
          type="button"
          variant="outline"
          className="w-full sm:w-auto"
          asChild
        >
          <a
            href={bookingUrl}
            target="_blank"
            rel="noopener noreferrer"
            aria-label={`Open booking preview for ${studioName}`}
          >
            Open preview
          </a>
        </Button>

        <Button
          type="button"
          variant="outline"
          className="w-full sm:w-auto"
          onClick={handleCopyIg}
          aria-label="Copy booking link for Instagram bio"
        >
          {copyIgLabel}
        </Button>
      </div>

      {/* Post-onboarding checklist */}
      <div className="border-t border-border mt-5 pt-5">
        {CHECKLIST_ITEMS.map(({ key, label, href }) => {
          const done = checklist[key]
          return (
            <div
              key={key}
              className="flex items-center justify-between py-2.5 border-b border-border last:border-b-0"
            >
              <div className="flex items-center gap-2.5">
                {done ? (
                  <CheckSquare
                    className="size-4 text-onyx shrink-0"
                    strokeWidth={2}
                    aria-hidden="true"
                  />
                ) : (
                  <Square
                    className="size-4 text-stone shrink-0"
                    strokeWidth={1.5}
                    aria-hidden="true"
                  />
                )}
                <span
                  className={cn(
                    'font-sans text-[14px] font-normal text-onyx',
                    done && 'line-through text-stone',
                  )}
                >
                  {label}
                </span>
              </div>
              <a
                href={href}
                aria-label={`Go to ${label}`}
                className="focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 rounded"
              >
                <ArrowRight className="size-3.5 text-stone" aria-hidden="true" />
              </a>
            </div>
          )
        })}
      </div>
    </div>
  )
}

'use client'

import { useEffect, useRef, useState } from 'react'
import { useForm, useWatch } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { toast } from 'sonner'
import { cn } from '@/lib/utils'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Typography } from '@/components/ui/typography'
import { TimezoneCombobox } from './TimezoneCombobox'
import { SlugPreview } from './SlugPreview'
import { saveStudioStep } from '@/app/actions/onboarding'
import { studioStepSchema, type StudioStepInput } from '@/lib/onboarding/schemas'

const SPECIALTY_OPTIONS = [
  'Blackwork',
  'Watercolor',
  'Traditional',
  'Neo-trad',
  'Realism',
  'Geometric',
  'Minimalist',
  'Portraits',
  'Script',
  'Cover-up',
]

interface StepStudioProfileProps {
  studioId: string
  userId: string
  initialFullName: string | null
  initialStudio: { name: string; slug: string; timezone: string } | null
  onNext: () => void
}

export function StepStudioProfile({
  studioId,
  initialFullName,
  initialStudio,
  onNext,
}: StepStudioProfileProps) {
  const nameInputRef = useRef<HTMLInputElement>(null)
  const [saving, setSaving] = useState(false)
  const [selectedSpecialties, setSelectedSpecialties] = useState<string[]>([])

  const {
    register,
    handleSubmit,
    setValue,
    control,
    formState: { errors },
  } = useForm<StudioStepInput>({
    resolver: zodResolver(studioStepSchema),
    defaultValues: {
      studioName: initialStudio?.name && initialStudio.name !== 'My Studio' ? initialStudio.name : '',
      timezone: initialStudio?.timezone ?? '',
      fullName: initialFullName ?? '',
      specialties: [],
    },
  })

  const watchedName = useWatch({ control, name: 'studioName' })

  // Autofocus studio name on mount
  useEffect(() => {
    nameInputRef.current?.focus()
  }, [])

  function toggleSpecialty(specialty: string) {
    setSelectedSpecialties((prev) => {
      const next = prev.includes(specialty)
        ? prev.filter((s) => s !== specialty)
        : [...prev, specialty]
      setValue('specialties', next)
      return next
    })
  }

  async function onSubmit(data: StudioStepInput) {
    setSaving(true)
    try {
      const result = await saveStudioStep(studioId, {
        ...data,
        specialties: selectedSpecialties,
      })
      if (!result.ok) {
        toast.error(result.error)
        return
      }
      onNext()
    } catch {
      toast.error("We couldn't save this step. Try again, or refresh the page.")
    } finally {
      setSaving(false)
    }
  }

  const { ref: nameReg, ...nameRegRest } = register('studioName')

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="space-y-5" noValidate>
      <div>
        <Typography
          variant="h1"
          as="h2"
          className="font-serif-italic font-normal"
          tabIndex={-1}
        >
          Your studio.
        </Typography>
        <p className="mt-1 font-sans text-[14px] text-stone">
          Two minutes to a live booking page.
        </p>
      </div>

      {/* Studio name */}
      <div className="space-y-1.5">
        <Label htmlFor="studioName" className="font-sans text-[11px] font-bold uppercase tracking-[0.08em] text-stone">
          Studio name <span className="text-destructive">*</span>
        </Label>
        <Input
          id="studioName"
          placeholder="Dark Matter Tattoo"
          autoComplete="organization"
          aria-describedby={errors.studioName ? 'studioName-error' : undefined}
          aria-invalid={!!errors.studioName}
          ref={(el) => {
            nameReg(el)
            ;(nameInputRef as React.MutableRefObject<HTMLInputElement | null>).current = el
          }}
          {...nameRegRest}
        />
        <SlugPreview studioName={watchedName ?? ''} />
        {errors.studioName && (
          <p id="studioName-error" role="alert" className="text-xs text-destructive">
            {errors.studioName.message}
          </p>
        )}
      </div>

      {/* Timezone */}
      <div className="space-y-1.5">
        <Label htmlFor="timezone" className="font-sans text-[11px] font-bold uppercase tracking-[0.08em] text-stone">
          Timezone <span className="text-destructive">*</span>
        </Label>
        <TimezoneCombobox
          id="timezone"
          value={watchedName !== undefined ? (control._formValues.timezone as string) ?? '' : ''}
          onValueChange={(tz) => setValue('timezone', tz, { shouldValidate: true })}
        />
        {errors.timezone && (
          <p role="alert" className="text-xs text-destructive">
            {errors.timezone.message}
          </p>
        )}
      </div>

      {/* Your name */}
      <div className="space-y-1.5">
        <Label htmlFor="fullName" className="font-sans text-[11px] font-bold uppercase tracking-[0.08em] text-stone">
          Your name <span className="text-destructive">*</span>
        </Label>
        <Input
          id="fullName"
          autoComplete="name"
          placeholder="Alex Rivera"
          aria-describedby={errors.fullName ? 'fullName-error' : undefined}
          aria-invalid={!!errors.fullName}
          {...register('fullName')}
        />
        {errors.fullName && (
          <p id="fullName-error" role="alert" className="text-xs text-destructive">
            {errors.fullName.message}
          </p>
        )}
      </div>

      {/* Specialties chip picker */}
      <div className="space-y-2">
        <Label className="font-sans text-[11px] font-bold uppercase tracking-[0.08em] text-stone">
          Your specialties <span className="text-stone font-normal normal-case tracking-normal">(optional)</span>
        </Label>
        <div className="flex flex-wrap gap-2" role="group" aria-label="Select specialties">
          {SPECIALTY_OPTIONS.map((specialty) => {
            const selected = selectedSpecialties.includes(specialty)
            return (
              <button
                key={specialty}
                type="button"
                onClick={() => toggleSpecialty(specialty)}
                aria-pressed={selected}
                className={cn(
                  'h-7 rounded-full border px-3 font-sans text-xs transition-colors',
                  selected
                    ? 'border-onyx bg-onyx text-bone'
                    : 'border-border bg-transparent text-stone hover:border-stone hover:text-onyx',
                )}
              >
                {specialty}
                {selected && <span className="ml-1" aria-hidden="true">×</span>}
              </button>
            )
          })}
        </div>
      </div>

      <div className="flex justify-end pt-2">
        <Button type="submit" disabled={saving} aria-busy={saving}>
          {saving ? 'Saving…' : 'Continue'}
        </Button>
      </div>
    </form>
  )
}

'use client'

import { useState } from 'react'
import { useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Typography } from '@/components/ui/typography'
import { saveLocationStep } from '@/app/actions/onboarding'
import { locationStepSchema, type LocationStepInput } from '@/lib/onboarding/schemas'

interface StepFirstLocationProps {
  studioId: string
  onNext: () => void
  onBack: () => void
  onSkip: () => void
}

export function StepFirstLocation({
  studioId,
  onNext,
  onBack,
  onSkip,
}: StepFirstLocationProps) {
  const [saving, setSaving] = useState(false)
  const [skipping, setSkipping] = useState(false)

  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm<LocationStepInput>({
    resolver: zodResolver(locationStepSchema),
    defaultValues: {
      locationName: 'Main Studio',
      country: 'United States',
    },
  })

  async function onSubmit(data: LocationStepInput) {
    setSaving(true)
    try {
