      if (!result.ok) {
        toast.error(result.error)
        return
      }
      onNext()
    } catch {
      toast.error("We couldn't save this step. Try again, or refresh the page.")
    } finally {
      setSaving(false)
    }
  }

  async function handleSkip() {
    setSkipping(true)
    try {
      const result = await saveLocationStep(studioId, {
        locationName: 'Main Studio',
        city: 'Unknown',
        country: 'United States',
      })
      if (!result.ok) {
        toast.error(result.error)
