          <Label htmlFor="city" className="font-sans text-[11px] font-bold uppercase tracking-[0.08em] text-stone">
            City <span className="text-destructive">*</span>
          </Label>
          <Input
            id="city"
            autoComplete="address-level2"
            aria-invalid={!!errors.city}
            aria-describedby={errors.city ? 'city-error' : undefined}
            {...register('city')}
          />
          {errors.city && (
            <p id="city-error" role="alert" className="text-xs text-destructive">
              {errors.city.message}
            </p>
          )}
        </div>

        <div className="space-y-1.5">
          <Label htmlFor="country" className="font-sans text-[11px] font-bold uppercase tracking-[0.08em] text-stone">
