          />
          {errors.country && (
            <p id="country-error" role="alert" className="text-xs text-destructive">
              {errors.country.message}
            </p>
          )}
        </div>
      </div>

      {/* Full address — optional, collapsed */}
      <details className="group rounded-lg border border-border bg-bone">
        <summary className="cursor-pointer list-none px-4 py-3 font-sans text-[13px] font-medium text-stone select-none hover:text-onyx transition-colors">
          Full address <span className="font-normal text-stone/70">(optional)</span>
        </summary>
        <div className="px-4 pb-4 space-y-3 border-t border-border pt-3">
          <div className="space-y-1.5">
            <Label htmlFor="address" className="font-sans text-[11px] font-bold uppercase tracking-[0.08em] text-stone">
              Street address
            </Label>
            <Input
              id="address"
              autoComplete="street-address"
              {...register('address')}
            />
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <Label htmlFor="state" className="font-sans text-[11px] font-bold uppercase tracking-[0.08em] text-stone">
                State / province
              </Label>
              <Input
                id="state"
                autoComplete="address-level1"
                {...register('state')}
              />
            </div>
            <div className="space-y-1.5">
              <Label htmlFor="zip" className="font-sans text-[11px] font-bold uppercase tracking-[0.08em] text-stone">
                ZIP / postal code
              </Label>
              <Input
                id="zip"
                autoComplete="postal-code"
                {...register('zip')}
              />
            </div>
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="phone" className="font-sans text-[11px] font-bold uppercase tracking-[0.08em] text-stone">
              Phone
            </Label>
            <Input
              id="phone"
              type="tel"
              autoComplete="tel"
              {...register('phone')}
            />
          </div>
        </div>
      </details>

      <div className="flex items-center justify-between pt-2">
        <Button type="button" variant="ghost" className="text-stone" onClick={onBack}>
          Back
        </Button>
        <div className="flex items-center gap-3">
          <Button
            type="button"
            variant="ghost"
            className="text-stone"
            disabled={skipping || saving}
            onClick={handleSkip}
          >
            {skipping ? 'Saving…' : 'Skip for now'}
          </Button>
          <Button type="submit" disabled={saving || skipping} aria-busy={saving}>
            {saving ? 'Saving…' : 'Continue'}
          </Button>
        </div>
      </div>
    </form>
  )
}

'use client'

import { useState } from 'react'
import { useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Typography } from '@/components/ui/typography'
import { ServiceTemplatePicker } from './ServiceTemplatePicker'
import { saveServiceStep } from '@/app/actions/onboarding'
import { serviceStepSchema, type ServiceStepInput } from '@/lib/onboarding/schemas'
import { type ServiceTemplate } from '@/lib/onboarding/service-templates'

interface StepFirstServiceProps {
  studioId: string
  onNext: () => void
  onBack: () => void
  onSkip: () => void
}

export function StepFirstService({
  studioId,
  onNext,
  onBack,
  onSkip,
}: StepFirstServiceProps) {
  const [saving, setSaving] = useState(false)
  const [skipping, setSkipping] = useState(false)
  const [selectedTemplateId, setSelectedTemplateId] = useState<string | null>(null)

  const {
    register,
    handleSubmit,
    reset,
    formState: { errors },
  } = useForm<ServiceStepInput>({
    resolver: zodResolver(serviceStepSchema),
    defaultValues: {
      serviceName: '',
      durationMin: 120,
      basePrice: 300,
      depositPct: 25,
    },
  })

  function handleTemplateSelect(templateId: string, tpl: ServiceTemplate) {
    setSelectedTemplateId(templateId)
    if (templateId === 'custom') {
      reset({
        serviceName: '',
        durationMin: 60,
        basePrice: 150,
        depositPct: 20,
        description: '',
      })
      return
    }
    reset({
      serviceName: tpl.name,
      durationMin: tpl.durationMin,
      basePrice: tpl.basePrice,
      depositPct: tpl.depositPct,
      description: 'description' in tpl ? (tpl.description ?? '') : '',
    })
  }

  async function onSubmit(data: ServiceStepInput) {
    setSaving(true)
    try {
      const result = await saveServiceStep(studioId, data)
      if (!result.ok) {
        toast.error(result.error)
        return
      }
      onNext()
    } catch {
      toast.error("We couldn't save this step. Try again, or refresh the page.")
    } finally {
      setSaving(false)
    }
  }

  async function handleSkip() {
    setSkipping(true)
    try {
      const result = await saveServiceStep(studioId, {
        serviceName: 'Custom Tattoo',
        durationMin: 120,
        basePrice: 300,
        depositPct: 25,
      })
      if (!result.ok) {
        toast.error(result.error)
        return
      }
      onSkip()
    } catch {
      toast.error("We couldn't skip this step. Try again, or refresh the page.")
    } finally {
      setSkipping(false)
    }
  }

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="space-y-5" noValidate>
      <div>
        <Typography
