import { useEffect, useRef, useState } from 'react'
import { useRouter } from 'next/navigation'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import { Typography } from '@/components/ui/typography'
import { BookingLinkCard } from './BookingLinkCard'
import { completeOnboarding } from '@/app/actions/onboarding'

interface StepBookingPageLiveProps {
  studioId: string
  slug: string
  studioName: string
  onBack: () => void
}

export function StepBookingPageLive({
  studioId,
  slug,
  studioName,
  onBack,
}: StepBookingPageLiveProps) {
  const router = useRouter()
  const completedRef = useRef(false)
  const [completing, setCompleting] = useState(false)

  // Fire completeOnboarding exactly once — guard against React Strict Mode double-invoke
  useEffect(() => {
    if (completedRef.current) return
    completedRef.current = true

    setCompleting(true)
    completeOnboarding(studioId)
      .then((result) => {
        if (!result.ok) {
          toast.error(result.error)
        }
      })
      .catch(() => {
        toast.error("We couldn't complete onboarding. Try again, or refresh the page.")
      })
      .finally(() => {
        setCompleting(false)
        // Clear localStorage draft state
        if (typeof window !== 'undefined') {
          localStorage.removeItem('inkos-onboarding-step')
        }
      })
  }, [studioId])

  function handleOpenStudio() {
    router.push('/dashboard')
  }

  return (
    <div className="space-y-6">
      <div>
        <Typography
          variant="h1"
          as="h2"
          className="font-serif-italic font-normal text-[32px] md:text-[36px]"
          tabIndex={-1}
        >
          Live.
        </Typography>
        <p className="mt-1 font-sans text-[14px] text-stone">
          Your booking page is public. Share the link.
        </p>
      </div>

      <BookingLinkCard slug={slug} studioName={studioName} />

      <div className="flex items-center justify-between pt-2">
        <Button
          type="button"
          variant="ghost"
          className="text-stone"
          onClick={onBack}
          disabled={completing}
        >
          Back
        </Button>
        <Button
          type="button"
          onClick={handleOpenStudio}
          disabled={completing}
          aria-busy={completing}
        >
          {completing ? 'Finishing…' : 'Open the studio'}
        </Button>
      </div>
    </div>
  )
}

'use client'

import { useEffect, useRef, useState } from 'react'
import { StepIndicator } from './StepIndicator'
import { StepStudioProfile } from './StepStudioProfile'
import { StepFirstLocation } from './StepFirstLocation'
import { StepFirstService } from './StepFirstService'
import { StepBookingPageLive } from './StepBookingPageLive'

const TOTAL_STEPS = 4
const STORAGE_KEY = 'inkos-onboarding-step'

const STEP_LABELS = [
  'YOUR STUDIO.',
  'LOCATION.',
  'FIRST SERVICE.',
  'LIVE.',
]

interface OnboardingWizardProps {
  studioId: string
  userId: string
  resumeAt: 1 | 2 | 3 | 4
  initialFullName: string | null
  initialStudio: { name: string; slug: string; timezone: string } | null
}

export function OnboardingWizard({
  studioId,
  userId,
  resumeAt,
  initialFullName,
  initialStudio,
}: OnboardingWizardProps) {
  const titleRef = useRef<HTMLHeadingElement>(null)

  const [currentStep, setCurrentStep] = useState<1 | 2 | 3 | 4>(() => {
    // Trust server resumeAt — but if localStorage is ahead, use that (UX softening)
    if (typeof window !== 'undefined') {
      const saved = localStorage.getItem(STORAGE_KEY)
      const parsed = saved ? parseInt(saved, 10) : NaN
      if (
        Number.isFinite(parsed) &&
        parsed >= 1 &&
        parsed <= TOTAL_STEPS &&
        parsed > resumeAt
      ) {
        return parsed as 1 | 2 | 3 | 4
      }
    }
    return resumeAt
  })

  // Persist current step to localStorage
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, String(currentStep))
  }, [currentStep])

  // Move focus to step title on step change (a11y)
  useEffect(() => {
    titleRef.current?.focus()
  }, [currentStep])

  // Track the slug from Step 1 so Step 4 can use it without a db round-trip
  const [slug, setSlug] = useState<string>(initialStudio?.slug ?? '')
  const [studioName, setStudioName] = useState<string>(initialStudio?.name ?? '')

  function goNext() {
    setCurrentStep((prev) => (Math.min(prev + 1, TOTAL_STEPS) as 1 | 2 | 3 | 4))
  }

  function goBack() {
    setCurrentStep((prev) => (Math.max(prev - 1, 1) as 1 | 2 | 3 | 4))
  }

  // Step 1 completion updates the slug for Step 4
  function handleStep1Next() {
    goNext()
  }

  return (
    <div className="min-h-screen bg-bone flex items-center justify-center px-4 py-8">
      <div className="w-full max-w-lg bg-bone rounded-2xl shadow-[var(--shadow-soft-md)] border border-border p-6 sm:p-10">
        {/* InkOS wordmark */}
        <div className="flex items-center gap-2.5 mb-8">
          <div className="flex h-8 w-8 items-center justify-center rounded-md bg-onyx shrink-0">
            <span className="font-serif-italic text-xl leading-none text-bone">i</span>
          </div>
          <div className="flex flex-col leading-tight">
            <span className="font-sans text-[18px] font-bold text-onyx tracking-tight">InkOS</span>
            <span className="font-sans text-[10px] font-semibold uppercase tracking-[0.08em] text-stone">
              Studio OS
            </span>
          </div>
        </div>

        {/* Step indicator */}
        <StepIndicator currentStep={currentStep} steps={STEP_LABELS} />

        {/* Step body — key forces React to remount on step change → triggers animate-in */}
        <div className="mt-10" key={currentStep}>
          <div className="animate-in fade-in-0 slide-in-from-bottom-1 duration-200 ease-out">
            {currentStep === 1 && (
              <StepStudioProfile
                studioId={studioId}
                userId={userId}
                initialFullName={initialFullName}
                initialStudio={initialStudio}
                onNext={() => {
                  handleStep1Next()
                }}
              />
            )}

            {currentStep === 2 && (
              <StepFirstLocation
                studioId={studioId}
                onNext={goNext}
                onBack={goBack}
                onSkip={goNext}
              />
            )}

            {currentStep === 3 && (
              <StepFirstService
                studioId={studioId}
                onNext={goNext}
                onBack={goBack}
                onSkip={goNext}
              />
            )}

            {currentStep === 4 && (
              <StepBookingPageLive
                studioId={studioId}
                slug={slug || (initialStudio?.slug ?? '')}
                studioName={studioName || (initialStudio?.name ?? '')}
                onBack={goBack}
              />
            )}
          </div>
        </div>

        {/* Hidden ref target for programmatic focus on step change */}
        <span
          ref={titleRef}
          tabIndex={-1}
          aria-hidden="true"
          className="sr-only"
        />
      </div>
    </div>
  )
}

